package co.golink.tester.ui.i18n

/**
 * Textos dos Recibos: cópia de `rcpt.*` dos JSON da web (resources/js/i18n/lang).
 * GERADO por ops/i18n/gen_i18n_receipts.py (repo web) — não editar à mão; mudar o JSON e voltar a gerar.
 * A chave é a da web; parâmetros `{name}`; plurais "um | vários" (ou "zero | um | vários") como no vue-i18n.
 */
object I18nReceipts {
    private fun col(): Int = when (I18n.lang) { I18n.EN -> 1; I18n.FR -> 2; I18n.ES -> 3; else -> 0 }

    private fun fill(text: String, params: Array<out Pair<String, Any?>>): String {
        var out = text
        for ((name, value) in params) out = out.replace("{$name}", value?.toString().orEmpty())
        return out
    }

    /** Texto na língua atual (lê [I18n.lang]: recompõe ao mudar). */
    fun t(key: String, vararg params: Pair<String, Any?>): String {
        val row = rows[key] ?: return key
        return fill(row[col()].substringBefore(" | "), params)
    }

    /** Plural do vue-i18n ($tc): 2 formas = [1, resto]; 3 formas = [0, 1, resto]. `n` também vai como {n}. */
    fun tc(key: String, n: Int, vararg params: Pair<String, Any?>): String {
        val row = rows[key] ?: return key
        val forms = row[col()].split(" | ")
        val text = when (forms.size) {
            1 -> forms[0]
            2 -> if (n == 1) forms[0] else forms[1]
            else -> forms[if (n == 0) 0 else if (n == 1) 1 else 2]
        }
        return fill(text, arrayOf("n" to n, "count" to n, *params))
    }

    fun has(key: String): Boolean = key in rows

